acct_passwords=apis.supervisor.show_account_passwords(); pw={a['account_name']:a['password'] for a in acct_passwords}
venmo_token=apis.venmo.login(username='normansmit@gmail.com', password=pw.get('venmo'))['access_token']

payment_request_id=6097
matches=[]
page_index=0
page_limit=20
while True:
    res=apis.venmo.show_sent_payment_requests(access_token=venmo_token, query='', status=None, page_index=page_index, page_limit=page_limit)
    print('page', page_index, 'n', len(res))
    if not res:
        break
    for r in res:
        if r.get('payment_request_id')==payment_request_id:
            matches.append(r)
    page_index+=1
    if page_index>50:
        break

print('matches', len(matches))
if matches:
    r=matches[0]
    print({k:r.get(k) for k in ['payment_request_id','amount','description','sender','receiver','created_at','approved_at','denied_at']})

